<div class="service-drawer-backdrop"><section class="service-drawer"><div class="service-drawer-header"><div><h2><?= e($title) ?></h2><small><?= $editing?'Update service details':'Create a new service' ?></small></div><a href="index.php?page=admin&amp;section=services">&times;</a></div><form method="post" action="index.php?page=admin&amp;section=<?= e($section) ?>&amp;id=<?= (int)$id ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><?php if($errors): ?><div class="alert alert-danger"><?php foreach($errors as $error): ?><div><?= e($error) ?></div><?php endforeach; ?></div><?php endif; ?><label class="form-label">Service Code<input class="form-control" value="<?= e($editing?$service['service_code']:'Auto generated') ?>" readonly><small>Auto generated</small></label><label class="form-label">Service Name *<input class="form-control" name="service_name" value="<?= e($input['service_name']) ?>" required></label><label class="form-label">Category *<span class="service-add-category"><a href="index.php?page=admin&amp;section=services">+ Add Category</a></span><select class="form-select" name="category_id" required><option value="0">Select category</option><?php foreach($categories as $category): ?><option value="<?= (int)$category['id'] ?>" <?= $input['category_id']==(int)$category['id']?'selected':'' ?>><?= e($category['category_name']) ?></option><?php endforeach; ?></select></label><label class="form-label">Description<textarea class="form-control" name="description" rows="3"><?= e($input['description']) ?></textarea></label><div class="row g-3"><div class="col-6"><label class="form-label">Price (Rs.) *<input class="form-control" type="number" min="0" step="0.01" name="price" value="<?= e($input['price']) ?>" required></label></div><div class="col-6"><label class="form-label">Duration (Minutes)<input class="form-control" type="number" min="0" name="duration_minutes" value="<?= e($input['duration']) ?>"></label></div></div><label class="form-label">Status<select class="form-select" name="status"><option value="active" <?= $input['status']==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= $input['status']==='inactive'?'selected':'' ?>>Inactive</select></label><div class="service-drawer-actions"><a class="btn btn-light" href="index.php?page=admin&amp;section=services">Cancel</a><button class="btn btn-danger">Save Service</button></div></form></section></div>
